INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('children-of-crisis-i', 'Children of Crisis', 'A Study of Courage and Fear', 'Children of Crisis', 1, 1967, 'children-of-crisis', NULL, 'The foundation. Black children pioneering school desegregation in the South — and the white children and adults on the other side of the door — rendered without melodrama and with extraordinary moral attention.', 'childrenofcrisis00colerich', 'Children of Crisis A Study of Courage and Fear Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('migrants-sharecroppers-mountaineers', 'Migrants, Sharecroppers, Mountaineers', 'Children of Crisis, Volume II', 'Children of Crisis', 2, 1971, 'children-of-crisis', 'Pulitzer Prize, 1973', 'The rural poor of the South and Appalachia — migrant farmworkers, sharecroppers, mountain families — and how poverty shapes a child''s sense of the possible. One of the two volumes that shared the 1973 Pulitzer.', NULL, 'Migrants Sharecroppers Mountaineers Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('the-south-goes-north', 'The South Goes North', 'Children of Crisis, Volume III', 'Children of Crisis', 3, 1972, 'children-of-crisis', 'Pulitzer Prize, 1973', 'The great migration from the inside, as Southern families — Black and white — reach the industrial North and meet a colder hardship. The Pulitzer-winning companion to Volume II.', 'southgoesnorth00colerich', 'The South Goes North Coles Children of Crisis');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('eskimos-chicanos-indians', 'Eskimos, Chicanos, Indians', 'Children of Crisis, Volume IV', 'Children of Crisis', 4, 1977, 'children-of-crisis', NULL, 'Children too often left out of the national story — Native American, Inuit and Alaska Native, and Mexican-American — and how heritage, land, and language anchor a child''s identity.', NULL, 'Eskimos Chicanos Indians Coles Children of Crisis');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('privileged-ones', 'Privileged Ones', 'The Well-Off and the Rich in America · Children of Crisis, Volume V', 'Children of Crisis', 5, 1977, 'children-of-crisis', NULL, 'Having spent a decade among the poor, Coles trains the same unflinching attention on the children of wealth — and gives the language a word for what he finds: entitlement.', 'privilegedoneswe00colerich', 'Privileged Ones Coles Children of Crisis');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('women-of-crisis-i', 'Women of Crisis', 'Lives of Struggle and Hope', NULL, NULL, 1978, 'documentary', NULL, 'With Jane Coles. The women whose voices the original series carried but did not foreground, given the center of the frame.', NULL, 'Women of Crisis Lives of Struggle and Hope Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('women-of-crisis-ii', 'Women of Crisis II', 'Lives of Work and Dreams', NULL, NULL, 1980, 'documentary', NULL, 'With Jane Coles. The second volume of the Coleses'' joint portrait of American women''s working lives.', NULL, 'Women of Crisis Lives of Work and Dreams Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('the-moral-life-of-children', 'The Moral Life of Children', NULL, NULL, NULL, 1986, 'trilogy', NULL, 'How children form a conscience — their startling capacity for moral seriousness, courage, and ethical struggle, often outpacing the adults around them.', 'morallifeofchild00cole_1', 'The Moral Life of Children Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('the-political-life-of-children', 'The Political Life of Children', NULL, NULL, NULL, 1986, 'trilogy', NULL, 'How children absorb nation, power, class, and conflict — what a child in Belfast, Soweto, or Boston already understands about the political world.', 'politicallifeofc00cole_0', 'The Political Life of Children Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('the-spiritual-life-of-children', 'The Spiritual Life of Children', NULL, NULL, NULL, 1990, 'trilogy', NULL, 'The questions children ask about God, death, and meaning — taken seriously, across faiths, as genuine theology rather than charming naivety.', 'spirituallifeofc00cole', 'The Spiritual Life of Children Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('the-call-of-stories', 'The Call of Stories', 'Teaching and the Moral Imagination', NULL, NULL, 1989, 'teaching-service', NULL, 'From his famous Harvard course: a case for reading novels as moral instruction — how Tolstoy, Chekhov, O''Connor, and Williams teach us to imagine other lives.', 'callofstoriestea0000cole_b0m9', 'The Call of Stories Teaching and the Moral Imagination Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('the-call-of-service', 'The Call of Service', 'A Witness to Idealism', NULL, NULL, 1993, 'teaching-service', NULL, 'On the moral life of those who give themselves to others — volunteers, activists, teachers — and the satisfactions and temptations of idealism.', NULL, 'The Call of Service A Witness to Idealism Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('the-moral-intelligence-of-children', 'The Moral Intelligence of Children', NULL, NULL, NULL, 1997, 'teaching-service', NULL, 'A practical, widely read distillation of what his fieldwork taught him about raising a child of good character.', NULL, 'The Moral Intelligence of Children Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('erik-h-erikson', 'Erik H. Erikson', 'The Growth of His Work', NULL, NULL, 1970, 'portrait', NULL, 'His study of the mentor who gave his fieldwork its intellectual home.', NULL, 'Erik H Erikson The Growth of His Work Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('walker-percy', 'Walker Percy', 'An American Search', NULL, NULL, 1978, 'portrait', NULL, 'On the novelist-physician whose Southern, searching Catholicism Coles deeply admired.', NULL, 'Walker Percy An American Search Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('flannery-oconnors-south', 'Flannery O''Connor''s South', NULL, NULL, NULL, 1980, 'portrait', NULL, 'A reading of the writer whose unsparing moral vision he taught for decades.', NULL, 'Flannery O''Connor''s South Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('dorothy-day', 'Dorothy Day', 'A Radical Devotion', NULL, NULL, 1987, 'portrait', NULL, 'The Catholic Worker founder he claimed as a spiritual mother, drawn from their long acquaintance.', NULL, 'Dorothy Day A Radical Devotion Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('simone-weil', 'Simone Weil', 'A Modern Pilgrimage', NULL, NULL, 1987, 'portrait', NULL, 'On the philosopher-mystic whose attention to affliction mirrored his own.', NULL, 'Simone Weil A Modern Pilgrimage Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('anna-freud', 'Anna Freud', 'The Dream of Psychoanalysis', NULL, NULL, 1992, 'portrait', NULL, 'A tribute to the pioneer of child analysis who encouraged his early work.', NULL, 'Anna Freud The Dream of Psychoanalysis Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('the-story-of-ruby-bridges', 'The Story of Ruby Bridges', NULL, NULL, NULL, 1995, 'childrens', NULL, 'Thirty-five years after he first saw her, Coles gave Ruby Bridges back to the children of a new generation. Illustrated by George Ford.', 'storyofrubybridg0000cole', 'The Story of Ruby Bridges Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('the-old-ones-of-new-mexico', 'The Old Ones of New Mexico', NULL, NULL, NULL, 1973, 'documentary', NULL, 'A documentary collaboration with photographer Alex Harris — Coles''s interviews paired with images of the elders of northern New Mexico.', NULL, 'The Old Ones of New Mexico Coles');
INSERT INTO works (slug,title,subtitle,series,volume,year,category,award,blurb,archive_id,archive_query) VALUES ('doing-documentary-work', 'Doing Documentary Work', NULL, NULL, NULL, 1997, 'documentary', NULL, 'Coles on his own craft — the ethics and art of observing other lives, reading Agee, Orwell, Dorothea Lange and William Carlos Williams as fellow witnesses. The closest thing he wrote to a manual for the method behind every other book.', 'doingdocumentary0000cole_m7d6', 'Doing Documentary Work Coles');
